def brands_build(outdir, write_page, models):
    """Брендовые хабы под топ-спрос Wordstat: /brands/{slug}.html"""
    from build import slug as _slug
    from catalog import shop_card_html as _card, PIDX as _pidx
    import html
    for bslug, brand, demand, line, title, desc, intro, intro2, pains_line, art_links, sku_ids, faqs in BRAND_HUBS:
        bmodels = [m for m in models if m['brand'].strip() == brand]
        rows = ''.join(
            '<tr><td><a href="/models/' + _slug(m['brand']) + '-' + _slug(m['model']) + '.html">' + html.escape(m['brand'] + ' ' + m['model']) + '</a></td>'
            '<td>' + html.escape(str(m.get('type') or '—')) + '</td>'
            '<td>' + html.escape(str(m.get('ac') or '—')) + ' / ' + html.escape(str(m.get('dc') or '—')) + '</td>'
            '<td>' + html.escape(str(m.get('freq') or '—')) + '</td></tr>' for m in bmodels)
        cards = ''.join(_card(_pidx[i]) for i in sku_ids)
        arts = ' · '.join('<a href="/blog/' + a + '.html">' + dict((sl, t) for sl, t, d in BLOG_ARTICLES).get(a, a) + '</a>' for a in art_links)
        faq_html_b = ''.join('<details class="p-4 my-2 border rounded bg-white"><summary class="font-semibold cursor-pointer">' + html.escape(q) + '</summary><p class="mt-2 text-sm text-gray-600">' + html.escape(a2) + '</p></details>' for q, a2 in faqs)
